// Узел дерева: переходы по символам и признак конца слова
class TrieNode {
  children = new Map<string, TrieNode>();
  isEnd = false;
}

class Trie {
  // Корень соответствует пустому префиксу
  private root = new TrieNode();

  insert(word: string): void {
    let node = this.root;
    for (const ch of word) {
      // Нет ребра по символу — создаём новый узел
      if (!node.children.has(ch)) {
        node.children.set(ch, new TrieNode());
      }
      node = node.children.get(ch)!;
    }
    // Помечаем, что здесь заканчивается вставленное слово
    node.isEnd = true;
  }

  search(word: string): boolean {
    // Слово есть, только если путь существует И в конце стоит пометка
    const node = this.walk(word);
    return node !== null && node.isEnd;
  }

  startsWith(prefix: string): boolean {
    // Для префикса достаточно, чтобы путь существовал
    return this.walk(prefix) !== null;
  }

  // Спускаемся по символам строки; null — если путь обрывается
  private walk(s: string): TrieNode | null {
    let node: TrieNode = this.root;
    for (const ch of s) {
      const next = node.children.get(ch);
      if (!next) return null;
      node = next;
    }
    return node;
  }
}

// Время: O(L) на каждую операцию, L — длина слова/префикса
// Память: O(суммарная длина вставленных слов) — по узлу на символ в худшем случае
